// Differential checks of OptionUnbox-faithful.js against Lean, generated by leanscript --check
import * as M from "./OptionUnbox-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test4(false)", () => M.test4(false), "none", false);
check("test4(true)", () => M.test4(true), "0", false);
check("test6(0n, 0n)", () => M.test6(0n, 0n), "0", false);
check("test6(0n, 2n)", () => M.test6(0n, 2n), "2", false);
check("test6(1n, 1n)", () => M.test6(1n, 1n), "1", false);
check("test6(2n, 0n)", () => M.test6(2n, 0n), "2", false);
check("test6(0n, 13n)", () => M.test6(0n, 13n), "2", false);
check("test6(1n, 5n)", () => M.test6(1n, 5n), "2", false);
check("test6(2n, 2n)", () => M.test6(2n, 2n), "2", false);
check("test6(5n, 1n)", () => M.test6(5n, 1n), "1", false);
check("test6(13n, 0n)", () => M.test6(13n, 0n), "13", false);
check("test6(2n, 13n)", () => M.test6(2n, 13n), "2", false);
check("test6(5n, 5n)", () => M.test6(5n, 5n), "2", false);
check("test6(13n, 2n)", () => M.test6(13n, 2n), "2", false);
check("test6(13n, 13n)", () => M.test6(13n, 13n), "2", false);

console.log(`OptionUnbox-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
